__aicore__ inline void SplitKVectorProcess(LocalTensor<float> ubSrc1, LocalTensor<float> ubSrc2,
                                           GlobalTensor<float> gmSrc, LocalTensor<T> ubDst, GlobalTensor<T> gmDst,
                                           uint64_t vIndex, uint64_t index, uint64_t currentLoop,
                                           uint64_t dataSizeToMove, uint64_t dataSize, uint64_t coreSize,
                                           uint64_t singleSize, uint64_t singleCoreNum, uint64_t singleCoreN,
                                           uint64_t n, uint64_t cnt, bool orderFlag)
{
    uint64_t dstOffset = 0;
    uint64_t burst = 1;
    uint64_t burstLen = dataSizeToMove;
    uint64_t srcGap = 0;
    uint64_t dstGap = 0;
    uint64_t nCoreTail = n - (cnt - 1) * singleCoreN;
    uint64_t gmOffset = currentLoop * dataSize + vIndex * coreSize;
    uint64_t tmpOffset = 0;

    if (orderFlag && index == cnt - 1) {
        uint64_t outNCoreTail = AlignTo256B(nCoreTail);
        burst = (dataSizeToMove / outNCoreTail);
        burstLen = nCoreTail;
        srcGap = (outNCoreTail - nCoreTail);
        dstGap = 0;
    }

    CopyGmToUbufAlign<float>(ubSrc1, gmSrc[gmOffset], burst, burstLen * sizeof(float), 0, 0, srcGap * sizeof(float),
                             dstGap * sizeof(float) / 32);

    for (uint64_t j = 1; j < singleCoreNum; ++j) {
        tmpOffset += (singleSize << 1);
        CopyGmToUbufAlign<float>(ubSrc2, gmSrc[gmOffset + tmpOffset], burst, burstLen * sizeof(float), 0, 0,
                                 srcGap * sizeof(float), dstGap * sizeof(float) / 32);
        // MTE2 to V, enable pingpong
        TPipeSetWaitFlag<HardEvent::MTE2_V>();
        Add(ubSrc1, ubSrc1, ubSrc2, burst * burstLen);
        TPipeSetWaitFlag<HardEvent::V_MTE2>();
    }
    PipeBarrier<PIPE_V>();
    if constexpr (sizeof(T) == sizeof(half)) {
        Cast(ubDst, ubSrc1, RoundMode::CAST_RINT, burst * burstLen);
    }

__aicore__ inline void MatMulBaseKernelSingleCoreSplitK<A_TYPE, B_TYPE, L0C_TYPE, OUTPUT_TYPE, BIAS_TYPE, BLOCK_TYPE,
                                                        MM_CFG, IS_NKM>::SetOrgShape()
{
    constexpr bool isFp32Output = sizeof(typename OUTPUT_TYPE::T) == sizeof(float);
    const uint64_t orgShapeN = isFp32Output ? block_.matmulTilingData_->matmulTiling.N : block_.params_.outNAlign;
    if constexpr (A_TYPE::format == CubeFormat::NZ && B_TYPE::format == CubeFormat::NZ) {
        mm_.SetOrgShape(block_.params_.alignedOriM, block_.params_.alignedOriN, block_.params_.alignedKaSize,
                        block_.params_.alignedKbSize, orgShapeN);
    } else if constexpr (A_TYPE::format == CubeFormat::NZ) {
        mm_.SetOrgShape(block_.params_.alignedOriM, block_.matmulTilingData_->matmulTiling.N,
                        block_.params_.alignedKaSize, block_.matmulTilingData_->matmulTiling.Kb, orgShapeN);
    } else if constexpr (B_TYPE::format == CubeFormat::NZ) {
        mm_.SetOrgShape(block_.matmulTilingData_->matmulTiling.M, block_.params_.alignedOriN,
                        block_.matmulTilingData_->matmulTiling.Ka, block_.params_.alignedKbSize, orgShapeN);
    } else {
        // fp32输出时不需要对齐写回，dstStride与ND 128B对齐场景一致，统一使用realN
        if (n128AlignFlag_ || isFp32Output) {
            mm_.SetOrgShape(block_.matmulTilingData_->matmulTiling.M, block_.matmulTilingData_->matmulTiling.N,
                            block_.matmulTilingData_->matmulTiling.Ka, block_.matmulTilingData_->matmulTiling.Kb,
                            block_.matmulTilingData_->matmulTiling.N);
        } else {
            mm_.SetOrgShape(block_.matmulTilingData_->matmulTiling.M, block_.matmulTilingData_->matmulTiling.N,
                            block_.matmulTilingData_->matmulTiling.Ka, block_.matmulTilingData_->matmulTiling.Kb,
                            block_.params_.outNAlign);
        }
    }
}
